def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'D'
    if n == 3:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    last_opp = opp[-1]
    last_my = my[-1]

    if opp[3] == 'D':
        if n >= 95:
            if last_opp == 'D' or (n == 98 and sum(1 for a in opp[-10:] if a == 'D') >= 2):
                return 'D'
            if n == 98:
                return 'C'
        return 'C'
    else:
        my_d = sum(1 for a in my if a == 'D')
        opp_d = sum(1 for a in opp if a == 'D')
        opp_def_rate = opp_d / n

        if opp_def_rate > 0.5:
            return 'D'

        if last_opp == 'D':
            if last_my == 'D':
                dd = 0
                for i in range(n-1, -1, -1):
                    if my[i] == 'D' and opp[i] == 'D':
                        dd += 1
                    else:
                        break
                if dd >= 4:
                    return 'C'
                if dd >= 2 and rng.random() < 0.5:
                    return 'C'
                return 'D'
            else:
                return 'D'

        if last_opp == 'C':
            if last_my == 'D':
                return 'C'

            if n >= 95:
                recent_opp_d = sum(1 for a in opp[-10:] if a == 'D')
                if recent_opp_d >= 3:
                    return 'D'
                if n == 98:
                    return 'C'
                return 'C'

            if my_d < 10:
                retal = 0
                forgiv = 0
                for i in range(n-1):
                    if my[i] == 'D':
                        if opp[i+1] == 'D':
                            retal += 1
                        else:
                            forgiv += 1
                total_probes = retal + forgiv
                if total_probes > 0:
                    p_retal = retal / total_probes
                    if p_retal < 0.2 and opp_def_rate < 0.2:
                        if rng.random() < 0.3:
                            return 'D'
                    elif p_retal < 0.4 and opp_def_rate < 0.3:
                        if rng.random() < 0.15:
                            return 'D'
            return 'C'

    return 'C'
